        $(document).ready( function() {
    
            $("#header").load("/slfamily/inc/head.jsp");
            
            $("#lnbWrap").load("/slfamily/inc/minwon_left.jsp", function(responseTxt, statusTxt, xhr){
                if(statusTxt == "success")
                    //alert("External content loaded successfully!");
                    newSideMenu3(3, 8, 3);
                if(statusTxt == "error")
                    alert("Error: " + xhr.status + ": " + xhr.statusText);
            });
            
            $("#relSys").load("/common/include/relSys.jsp");
            $("#footSitemapWrap").load("/slfamily/inc/footSitemapWrap.jsp");
            $("#footer").load("/slfamily/inc/foot.jsp"); 
            $("#mobileMenuWrap").load("/slfamily/inc/mobileMenuWrap.jsp"); 
            
		 	// Tab
			$(".tab .tabTitle2 > li").click(function(){
				$(".tab .tabTitle2 > li").removeClass("active");
				$(this).addClass("active");
				
				$(".tab .tabContent").removeClass("active");
				var activeTab = $(this).attr('class').split(" ")[0];
			
				$("#" + activeTab).addClass("active");
			});
        });
